import pandas as pd


def run(inputs: dict) -> dict:
    target_state = inputs['target_state'].copy()
    cdc_events = inputs['cdc_events'].copy()

    # At-least-once delivery: distinct by seq (apply each event once)
    cdc_events = cdc_events.drop_duplicates(subset=['seq'], keep='first')

    # Sort by seq - the only trustworthy ordering
    cdc_events = cdc_events.sort_values('seq', kind='mergesort')

    # Original last_seq per order, used for the replay guard (fixed, does not
    # change as we apply events within this batch).
    orig_last_seq = {}
    state = {}
    for _, row in target_state.iterrows():
        oid = row['order_id']
        orig_last_seq[oid] = row['last_seq']
        state[oid] = {
            'status': row['status'],
            'amount': row['amount'],
            'last_seq': row['last_seq'],
        }

    deleted = {}  # order_id -> deleted_seq, only valid if order currently has no row

    for _, ev in cdc_events.iterrows():
        oid = ev['order_id']
        seq = ev['seq']
        op = ev['op']
        status = ev['status']
        amount = ev['amount']

        # Replay guard: based on ORIGINAL target_state last_seq
        if oid in orig_last_seq and seq <= orig_last_seq[oid]:
            continue

        if op == 'D':
            if oid in state:
                del state[oid]
                deleted[oid] = seq
            # D for a missing order does nothing
        else:  # 'I' or 'U'
            if oid in state:
                existing = state[oid]
                if op == 'U' and pd.isna(amount):
                    new_amount = existing['amount']
                else:
                    new_amount = amount
                state[oid] = {
                    'status': status,
                    'amount': new_amount,
                    'last_seq': seq,
                }
            else:
                state[oid] = {
                    'status': status,
                    'amount': amount,
                    'last_seq': seq,
                }
            # row recreated/updated, no longer deleted
            deleted.pop(oid, None)

    # Build new_state
    if state:
        new_state_rows = [
            {
                'order_id': oid,
                'status': vals['status'],
                'amount': vals['amount'],
                'last_seq': vals['last_seq'],
            }
            for oid, vals in state.items()
        ]
        new_state = pd.DataFrame(new_state_rows, columns=['order_id', 'status', 'amount', 'last_seq'])
    else:
        new_state = pd.DataFrame(columns=['order_id', 'status', 'amount', 'last_seq'])

    # Build tombstones
    if deleted:
        tomb_rows = [
            {'order_id': oid, 'deleted_seq': seq}
            for oid, seq in deleted.items()
        ]
        tombstones = pd.DataFrame(tomb_rows, columns=['order_id', 'deleted_seq'])
    else:
        tombstones = pd.DataFrame(columns=['order_id', 'deleted_seq'])

    return {
        'new_state': new_state,
        'tombstones': tombstones,
    }
